// Data/Creatures.lua, as the export writes it.

import { quote } from "../../../lib/dungeons.mjs";

/** The Lua file, "\r\n"-joined: `rows` is [{ map, key, creature, display }], any with neither left out. */
export function renderCreatures(rows) {
  const maps = {};
  for (const row of rows) if (row.creature || row.display) (maps[row.map] ??= []).push(row);
  const lines = [
    "-- GENERATED by pipelines/places/tools/bosses/export.mjs from the boss tables (make bosses-export). Their creatures come from",
    "-- boss_creatures.py (the Forever repack's world database) and the client's own tables (wago.tools).",
    "--",
    "-- SpokenBossCreatures[instance map][boss key] = { creature = the boss's creature id (nil where only the guide",
    "-- knows the boss), display = its first model's display id (nil where there is none) }: its portrait. A boss",
    "-- with no creature here has no portrait.",
    "",
    "SpokenBossCreatures = {",
  ];
  for (const map of Object.keys(maps).map(Number).sort((a, b) => a - b)) {
    lines.push(`\t[${map}] = {`);
    for (const boss of [...maps[map]].sort((a, b) => a.key.localeCompare(b.key))) {
      lines.push(`\t\t[${quote(boss.key)}] = { creature = ${boss.creature ?? "nil"}, display = ${boss.display ?? "nil"} },`);
    }
    lines.push("\t},");
  }
  lines.push("}", "");
  return lines.join("\r\n");
}
